/* Private E1 split recipe; generated synchronously from the document token closure. */
@layer proto-ui {
:host([data-pui-split-root-style]) {
  --pui-split-motion-recipe: h1;
  --pui-split-participation-coordinate-recipe: i1;
  --pui-split-intrinsic-nowrap-recipe: v1;
  --pui-split-dialog-motion-recipe: k1;
  --pui-split-native-text-recipe: l1;
  --pui-split-inline-display: initial;
  --pui-translate-x: initial;
  --pui-translate-y: initial;
  --pui-scale-x: initial;
  --pui-scale-y: initial;
  --pui-split-rest-transform: initial;
  --pui-split-border-uniform: 0px;
  --pui-enter-scale: initial;
  --pui-exit-scale: initial;
  --pui-enter-opacity: initial;
  --pui-exit-opacity: initial;
  --pui-animation-duration: initial;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr);
  box-sizing: border-box;
  border-style: solid;
  border-color: transparent;
  --pui-split-padding-top: 0px;
  --pui-split-border-top: 0px;
  padding-top: var(--pui-split-padding-top);
  border-top-width: var(--pui-split-border-top);
  --pui-split-padding-right: 0px;
  --pui-split-border-right: 0px;
  padding-right: var(--pui-split-padding-right);
  border-right-width: var(--pui-split-border-right);
  --pui-split-padding-bottom: 0px;
  --pui-split-border-bottom: 0px;
  padding-bottom: var(--pui-split-padding-bottom);
  border-bottom-width: var(--pui-split-border-bottom);
  --pui-split-padding-left: 0px;
  --pui-split-border-left: 0px;
  padding-left: var(--pui-split-padding-left);
  border-left-width: var(--pui-split-border-left);
  --pui-split-compiled-receipt: t7xyck;
}
:host([data-pui-split-root-style~="inline-flex"][data-pui-split-root-style~="flex-1"][data-pui-split-root-style~="whitespace-nowrap"]) {
  --pui-split-inline-display: inline-flex;
}
:host([data-pui-split-root-style~="inline-flex"][data-pui-split-root-style~="flex-1"][data-pui-split-root-style~="whitespace-nowrap"]) > [data-pui-split-surface] {
  flex: 1 1 auto;
}
:host([data-pui-split-root-style]) > [data-pui-split-surface]:not(input, textarea) {
  box-sizing: border-box;
  min-width: 0;
  min-height: 0;
  align-self: stretch;
  justify-self: stretch;
  margin-top: calc(0px - var(--pui-split-padding-top) - var(--pui-split-border-top));
  margin-right: calc(0px - var(--pui-split-padding-right) - var(--pui-split-border-right));
  margin-bottom: calc(0px - var(--pui-split-padding-bottom) - var(--pui-split-border-bottom));
  margin-left: calc(0px - var(--pui-split-padding-left) - var(--pui-split-border-left));
}
:host([data-pui-split-root-style][data-pui-split-text-control]) {
  display: block;
  padding: 0;
  border-width: 0;
}
}
